SELECT FROM sys_user
AND user_id = #{userId}
AND LOWER(username) LIKE ('%' + LOWER(#{username}) + '%')
AND LOWER(full_name) LIKE ('%' + LOWER(#{fullName}) + '%')
AND LOWER(email) LIKE ('%' + LOWER(#{email}) + '%')
AND phone LIKE ('%' + #{phone} + '%')
AND role_id = #{roleId}
AND [status] = #{status}
ORDER BY created_at DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(user_id)
FROM sys_user


        AND user_id = #{userId}


        AND LOWER(username) LIKE ('%' + LOWER(#{username}) + '%')


        AND LOWER(full_name) LIKE ('%' + LOWER(#{fullName}) + '%')


        AND LOWER(email) LIKE ('%' + LOWER(#{email}) + '%')


        AND phone LIKE ('%' + #{phone} + '%')


        AND role_id = #{roleId}


        AND [status] = #{status}

SELECT COUNT(*)
FROM [sys_user]
WHERE YEAR([created_at]) = #{year}
AND MONTH([created_at]) = #{month}
AND [status] != 'deleted'
